952	#[derive(Debug, Copy, Clone)]
953	enum RowGroupKind {
954	    Header,
955	    Footer,
956	}
957	
958	impl RowGroupKind {
959	    fn name(self) -> &'static str {
960	        match self {
961	            Self::Header => "header",
962	            Self::Footer => "footer",
963	        }
964	    }
