1808	    /// Generate the final headers and footers:
1809	    ///
1810	    /// 1. Convert gutter-ignorant to gutter-aware indices if necessary;
1811	    /// 2. Expand the header downwards (or footer upwards) to also include
1812	    ///    an adjacent gutter row to be repeated alongside that header or
1813	    ///    footer, if there is gutter;
1814	    /// 3. Wrap headers and footers in the correct [`Repeatable`] variant.
1815	    fn finalize_headers_and_footers(
1816	        &self,
1817	        has_gutter: bool,
1818	        headers: &mut [Repeatable<Header>],
1819	        footer: Option<(usize, Span, Footer)>,
1820	        repeat_footer: bool,
1821	        row_amount: usize,
1822	        at_least_one_cell: bool,
1823	    ) -> SourceResult<Option<Repeatable<Footer>>> {
1824	        headers.sort_unstable_by_key(|h| h.range.start);
1825	
1826	        // Mark consecutive headers in those positions as short-lived:
1827	        // (a) before a header of lower level;
1828	        // (b) right before the end of the table or the final footer;
1829	        // That's because they would stop repeating immediately, so don't even
1830	        // attempt to.
1831	        //
1832	        // It is important to do this BEFORE we update header and footer ranges
1833	        // due to gutter below as 'row_amount' doesn't consider gutter.
1834	        //
1835	        // TODO(subfooters): take the last footer if it is at the end and
1836	        // backtrack through consecutive footers until the first one in the
1837	        // sequence is found. If there is no footer at the end, there are no
1838	        // headers to turn short-lived.
1839	        let mut consecutive_header_start =
1840	            footer.as_ref().map(|(_, _, f)| f.start).unwrap_or(row_amount);
1841	        let mut last_consec_level = 0;
1842	        for header in headers.iter_mut().rev() {
1843	            if header.range.end == consecutive_header_start
1844	                && header.level.get() >= last_consec_level
1845	            {
1846	                header.short_lived = true;
1847	            } else {
1848	                last_consec_level = header.level.get();
1849	            }
1850	
1851	            consecutive_header_start = header.range.start;
1852	        }
1853	
1854	        // Repeat the gutter below a header (hence why we don't
1855	        // subtract 1 from the gutter case).
1856	        // Don't do this if there are no rows under the header.
1857	        if has_gutter {
1858	            for header in &mut *headers {
1859	                // Index of first y is doubled, as each row before it
1860	                // receives a gutter row below.
1861	                header.range.start *= 2;
1862	
1863	                // - 'header.end' is always 'last y + 1'. The header stops
1864	                // before that row.
1865	                // - Therefore, '2 * header.end' will be 2 * (last y + 1),
1866	                // which is the adjusted index of the row before which the
1867	                // header stops, meaning it will still stop right before it
1868	                // even with gutter thanks to the multiplication below.
1869	                // - This means that it will span all rows up to
1870	                // '2 * (last y + 1) - 1 = 2 * last y + 1', which equates
1871	                // to the index of the gutter row right below the header,
1872	                // which is what we want (that gutter spacing should be
1873	                // repeated across pages to maintain uniformity).
1874	                header.range.end *= 2;
1875	
1876	                // If the header occupies the entire grid, ensure we don't
1877	                // include an extra gutter row when it doesn't exist, since
1878	                // the last row of the header is at the very bottom,
1879	                // therefore '2 * last y + 1' is not a valid index.
1880	                let row_amount = (2 * row_amount).saturating_sub(1);
1881	                header.range.end = header.range.end.min(row_amount);
1882	            }
1883	        }
1884	
1885	        let footer = footer
1886	            .map(|(footer_end, footer_span, mut footer)| {
1887	                if footer_end != row_amount {
1888	                    bail!(footer_span, "footer must end at the last row");
1889	                }
1890	
1891	                // TODO(subfooters): will need a global slice of headers and
1892	                // footers for when we have multiple footers
1893	                // Alternatively, never include the gutter in the footer's
1894	                // range and manually add it later on layout. This would allow
1895	                // laying out the gutter as part of both the header and footer,
1896	                // and, if the page only has headers, the gutter row below the
1897	                // header is automatically removed (as it becomes the last), so
1898	                // only the gutter above the footer is kept, ensuring the same
1899	                // gutter row isn't laid out two times in a row. When laying
1900	                // out the footer for real, the mechanism can be disabled.
1901	                let last_header_end = headers.last().map(|header| header.range.end);
1902	
1903	                if has_gutter {
1904	                    // Convert the footer's start index to post-gutter coordinates.
1905	                    footer.start *= 2;
1906	
1907	                    // Include the gutter right before the footer, unless there is
1908	                    // none, or the gutter is already included in the header (no
1909	                    // rows between the header and the footer).
1910	                    if last_header_end != Some(footer.start) {
1911	                        footer.start = footer.start.saturating_sub(1);
1912	                    }
1913	
1914	                    // Adapt footer end but DO NOT include the gutter below it,
1915	                    // if it exists. Calculation:
1916	                    // - Starts as 'last y + 1'.
1917	                    // - The result will be
1918	                    // 2 * (last_y + 1) - 1 = 2 * last_y + 1,
1919	                    // which is the new index of the last footer row plus one,
1920	                    // meaning we do exclude any gutter below this way.
1921	                    //
1922	                    // It also keeps us within the total amount of rows, so we
1923	                    // don't need to '.min()' later.
1924	                    footer.end = (2 * footer.end).saturating_sub(1);
1925	                }
1926	
1927	                Ok(footer)
1928	            })
1929	            .transpose()?
1930	            .map(|footer| {
1931	                // Don't repeat footers when the table only has headers and
1932	                // footers.
1933	                // TODO(subfooters): Switch this to marking the last N
1934	                // consecutive footers as short lived.
1935	                Repeatable {
1936	                    inner: footer,
1937	                    repeated: repeat_footer && at_least_one_cell,
1938	                }
1939	            });
1940	
1941	        Ok(footer)
1942	    }
