1992	/// Given the existing range of a row group (header or footer), tries to expand
1993	/// it to fit the new cell placed inside it. If the newly-expanded row group
1994	/// would conflict with existing cells or other row groups, an error is
1995	/// returned. Otherwise, the new `start..end` range of rows in the row group is
1996	/// returned.
1997	fn expand_row_group(
1998	    resolved_cells: &[Option<Entry>],
1999	    group_range: Option<&Range<usize>>,
2000	    group_kind: RowGroupKind,
2001	    first_available_row: usize,
2002	    cell_y: usize,
2003	    rowspan: usize,
2004	    columns: usize,
2005	) -> HintedStrResult<Range<usize>> {
2006	    // Ensure each cell in a header or footer is fully contained within it by
2007	    // expanding the header or footer towards this new cell.
2008	    let (new_group_start, new_group_end) = group_range
2009	        .map_or((cell_y, cell_y + rowspan), |r| {
2010	            (r.start.min(cell_y), r.end.max(cell_y + rowspan))
2011	        });
2012	
2013	    // This check might be unnecessary with the loop below, but let's keep it
2014	    // here for full correctness.
2015	    //
2016	    // Quickly detect the case:
2017	    // y = 0 => occupied
2018	    // y = 1 => empty
2019	    // y = 2 => header
2020	    // and header tries to expand to y = 0 - invalid, as
2021	    // 'y = 1' is the earliest row it can occupy.
2022	    if new_group_start < first_available_row {
2023	        bail!(
2024	            "cell would cause {} to expand to non-empty row {}",
2025	            group_kind.name(),
2026	            first_available_row.saturating_sub(1);
2027	            hint: "try moving its cells to available rows";
2028	        );
2029	    }
2030	
2031	    let new_rows =
2032	        group_range.map_or((new_group_start..new_group_end).chain(0..0), |r| {
2033	            // NOTE: 'r.end' is one row AFTER the row group's last row, so it
2034	            // makes sense to check it if 'new_group_end > r.end', that is, if
2035	            // the row group is going to expand. It is NOT a duplicate check,
2036	            // as we hadn't checked it before (in a previous run, it was
2037	            // 'new_group_end' at the exclusive end of the range)!
2038	            //
2039	            // NOTE: To keep types the same, we have to always return
2040	            // '(range).chain(range)', which justifies chaining an empty
2041	            // range above.
2042	            (new_group_start..r.start).chain(r.end..new_group_end)
2043	        });
2044	
2045	    // The check above isn't enough, however, even when the header is expanding
2046	    // upwards, as it might expand upwards towards an occupied row after the
2047	    // first empty row, e.g.
2048	    //
2049	    // y = 0 => occupied
2050	    // y = 1 => empty (first_available_row = 1)
2051	    // y = 2 => occupied
2052	    // y = 3 => header
2053	    //
2054	    // Here, we should bail if the header tries to expand upwards, regardless
2055	    // of the fact that the conflicting row (y = 2) comes after the first
2056	    // available row.
2057	    //
2058	    // Note that expanding upwards is only possible when row-positioned cells
2059	    // are specified, in one of the following cases:
2060	    //
2061	    // 1. We place e.g. 'table.cell(y: 3)' followed by 'table.cell(y: 2)'
2062	    // (earlier row => upwards);
2063	    //
2064	    // 2. We place e.g. 'table.cell(y: 3)' followed by '[a]' (auto-pos cell
2065	    // favors 'first_available_row', so the header tries to expand upwards to
2066	    // place the cell at 'y = 1' and conflicts at 'y = 2') or
2067	    // 'table.cell(x: 1)' (same deal).
2068	    //
2069	    // Of course, we also need to check for downward expansion as usual as
2070	    // there could be a non-empty row below the header, but the upward case is
2071	    // highlighted as it was checked separately before (and also to explain
2072	    // what kind of situation we are preventing with this check).
2073	    //
2074	    // Note that simply checking for non-empty rows like below not only
2075	    // prevents conflicts with top-level cells (outside of headers and
2076	    // footers), but also prevents conflicts with other headers or footers,
2077	    // since we have an invariant that even empty headers and footers must
2078	    // contain at least one 'Some(...)' position in 'resolved_cells'. More
2079	    // precisely, each header and footer has at least one 'Some(...)' cell at
2080	    // 'group_range.start' and at 'group_range.end - 1' - non-empty headers and
2081	    // footers don't span any unnecessary rows. Therefore, we don't have to
2082	    // loop over headers and footers, only check if the new rows are empty.
2083	    for new_y in new_rows {
2084	        if let Some(new_row @ [_non_empty, ..]) = resolved_cells
2085	            .get(new_y * columns..)
2086	            .map(|cells| &cells[..columns.min(cells.len())])
2087	        {
2088	            if new_row.iter().any(Option::is_some) {
2089	                bail!(
2090	                    "cell would cause {} to expand to non-empty row {new_y}",
2091	                    group_kind.name();
2092	                    hint: "try moving its cells to available rows";
2093	                )
2094	            }
2095	        } else {
2096	            // Received 'None' or an empty slice, so we are expanding the
2097	            // header or footer into new rows, which is always valid and cannot
2098	            // conflict with existing cells. (Note that we only resize
2099	            // 'resolved_cells' after this function is called, so, if this
2100	            // header or footer is at the bottom of the table so far, this loop
2101	            // will end quite early, regardless of where this cell was placed
2102	            // or of its rowspan value.)
2103	            break;
2104	        }
2105	    }
2106	
2107	    Ok(new_group_start..new_group_end)
2108	}
