2150	/// Given a cell's requested x and y, the vector with the resolved cell
2151	/// positions, the `auto_index` counter (determines the position of the next
2152	/// `(auto, auto)` cell) and the amount of columns in the grid, returns the
2153	/// final index of this cell in the vector of resolved cells.
2154	///
2155	/// The `first_available_row` parameter is used by headers and footers to
2156	/// indicate the first empty row available. Any rows before those should
2157	/// not be picked by cells with `auto` row positioning, since headers and
2158	/// footers occupy entire rows, and may not conflict with cells outside them.
2159	#[expect(clippy::too_many_arguments)]
2160	fn resolve_cell_position(
2161	    cell_x: Smart<usize>,
2162	    cell_y: Smart<usize>,
2163	    colspan: usize,
2164	    rowspan: usize,
2165	    header_rows: &SmallBitSet,
2166	    headers: &[Repeatable<Header>],
2167	    footer: Option<&(usize, Span, Footer)>,
2168	    resolved_cells: &[Option<Entry>],
2169	    auto_index: &mut usize,
2170	    first_available_row: usize,
2171	    columns: usize,
2172	    in_row_group: bool,
2173	) -> HintedStrResult<usize> {
2174	    // Translates a (x, y) position to the equivalent index in the final cell vector.
2175	    // Errors if the position would be too large.
2176	    let cell_index = |x, y: usize| {
2177	        y.checked_mul(columns)
2178	            .and_then(|row_index| row_index.checked_add(x))
2179	            .ok_or_else(|| HintedString::from(eco_format!("cell position too large")))
2180	    };
2181	    match (cell_x, cell_y) {
2182	        // Fully automatic cell positioning. The cell did not
2183	        // request a coordinate.
2184	        (Smart::Auto, Smart::Auto) => {
2185	            // Let's find the first available position starting from the
2186	            // automatic position counter, searching in row-major order.
2187	            // Note that the counter ignores any cells with fixed positions,
2188	            // but automatically-positioned cells will avoid conflicts by
2189	            // simply skipping existing cells, headers and footers.
2190	            let resolved_index = find_next_available_position(
2191	                header_rows,
2192	                footer,
2193	                resolved_cells,
2194	                columns,
2195	                *auto_index,
2196	                false,
2197	            )?;
2198	
2199	            // Ensure the next cell with automatic position will be
2200	            // placed after this one (maybe not immediately after).
2201	            //
2202	            // The calculation below also affects the position of the upcoming
2203	            // automatically-positioned lines, as they are placed below
2204	            // (horizontal lines) or to the right (vertical lines) of the cell
2205	            // that would be placed at 'auto_index'.
2206	            *auto_index = if colspan == columns {
2207	                // The cell occupies all columns, so no cells can be placed
2208	                // after it until all of its rows have been spanned.
2209	                resolved_index + colspan * rowspan
2210	            } else {
2211	                // The next cell will have to be placed at least after its
2212	                // spanned columns.
2213	                resolved_index + colspan
2214	            };
2215	
2216	            Ok(resolved_index)
2217	        }
2218	        // Cell has chosen at least its column.
2219	        (Smart::Custom(cell_x), cell_y) => {
2220	            if cell_x >= columns {
2221	                return Err(HintedString::from(eco_format!(
2222	                    "cell could not be placed at invalid column {cell_x}"
2223	                )));
2224	            }
2225	            if let Smart::Custom(cell_y) = cell_y {
2226	                // Cell has chosen its exact position.
2227	                //
2228	                // Ensure it doesn't conflict with an existing header or
2229	                // footer (but only if it isn't already in one, otherwise there
2230	                // will already be a separate check).
2231	                if !in_row_group {
2232	                    check_for_conflicting_cell_row(
2233	                        header_rows,
2234	                        headers,
2235	                        footer,
2236	                        cell_y,
2237	                        rowspan,
2238	                    )?;
2239	                }
2240	
2241	                cell_index(cell_x, cell_y)
2242	            } else {
2243	                // Cell has only chosen its column.
2244	                // Let's find the first row which has that column available.
2245	                // If in a header or footer, start searching by the first empty
2246	                // row / the header or footer's first row (specified through
2247	                // 'first_available_row'). Otherwise, start searching at the
2248	                // first row.
2249	                let initial_index = cell_index(cell_x, first_available_row)?;
2250	
2251	                // Try each row until either we reach an absent position at the
2252	                // requested column ('Some(None)') or an out of bounds position
2253	                // ('None'), in which case we'd create a new row to place this
2254	                // cell in.
2255	                find_next_available_position(
2256	                    header_rows,
2257	                    footer,
2258	                    resolved_cells,
2259	                    columns,
2260	                    initial_index,
2261	                    true,
2262	                )
2263	            }
2264	        }
2265	        // Cell has only chosen its row, not its column.
2266	        (Smart::Auto, Smart::Custom(cell_y)) => {
2267	            // Ensure it doesn't conflict with an existing header or
2268	            // footer (but only if it isn't already in one, otherwise there
2269	            // will already be a separate check).
2270	            if !in_row_group {
2271	                check_for_conflicting_cell_row(
2272	                    header_rows,
2273	                    headers,
2274	                    footer,
2275	                    cell_y,
2276	                    rowspan,
2277	                )?;
2278	            }
2279	
2280	            // Let's find the first column which has that row available.
2281	            let first_row_pos = cell_index(0, cell_y)?;
2282	            let last_row_pos = first_row_pos
2283	                .checked_add(columns)
2284	                .ok_or_else(|| eco_format!("cell position too large"))?;
2285	
2286	            (first_row_pos..last_row_pos)
2287	                .find(|possible_index| {
2288	                    // Much like in the previous cases, we skip any occupied
2289	                    // positions until we either reach an absent position
2290	                    // (`Some(None)`) or an out of bounds position (`None`),
2291	                    // in which case we can just expand the vector enough to
2292	                    // place this cell. In either case, we found an available
2293	                    // position.
2294	                    !matches!(resolved_cells.get(*possible_index), Some(Some(_)))
2295	                })
2296	                .ok_or_else(|| {
2297	                    eco_format!(
2298	                        "cell could not be placed in row {cell_y} because it was full"
2299	                    )
2300	                })
2301	                .hint("try specifying your cells in a different order")
2302	        }
2303	    }
2304	}
2305	
2306	/// Finds the first available position after the initial index in the resolved
2307	/// grid of cells. Skips any non-absent positions (positions which already
2308	/// have cells specified by the user) as well as any headers and footers.
2309	///
2310	/// When `skip_rows` is true, one row is skipped on each iteration, preserving
2311	/// the column. That is used to find a position for a fixed column cell.
2312	#[inline]
2313	fn find_next_available_position(
2314	    header_rows: &SmallBitSet,
2315	    footer: Option<&(usize, Span, Footer)>,
2316	    resolved_cells: &[Option<Entry>],
2317	    columns: usize,
2318	    initial_index: usize,
2319	    skip_rows: bool,
2320	) -> HintedStrResult<usize> {
2321	    let mut resolved_index = initial_index;
2322	
2323	    loop {
2324	        if let Some(Some(_)) = resolved_cells.get(resolved_index) {
2325	            // Skip any non-absent cell positions (`Some(None)`) to
2326	            // determine where this cell will be placed. An out of
2327	            // bounds position (thus `None`) is also a valid new
2328	            // position (only requires expanding the vector).
2329	            if skip_rows {
2330	                // Skip one row at a time (cell chose its column, so we don't
2331	                // change it).
2332	                resolved_index =
2333	                    resolved_index.checked_add(columns).ok_or_else(|| {
2334	                        HintedString::from(eco_format!("cell position too large"))
2335	                    })?;
2336	            } else {
2337	                // Ensure we don't run unnecessary checks in the hot path
2338	                // (for fully automatically-positioned cells). Memory usage
2339	                // would become impractically large before this overflows.
2340	                resolved_index += 1;
2341	            }
2342	        } else if header_rows.contains(resolved_index / columns) {
2343	            // Skip header rows (can't place a cell inside it from outside it).
2344	            if skip_rows {
2345	                // Ensure the cell's chosen column is kept after the header.
2346	                resolved_index += columns;
2347	            } else {
2348	                // Skip to the start of the next row.
2349	                //
2350	                // Add 1 to resolved index to force moving to the next row if
2351	                // this is at the start of one. At the end of one, '+ 1'
2352	                // already pushes to the next one and 'next_multiple_of' does
2353	                // not modify it, so nothing bad happens then either.
2354	                resolved_index = (resolved_index + 1).next_multiple_of(columns);
2355	            }
2356	        } else if let Some((footer_end, _, footer)) = footer
2357	            && resolved_index >= footer.start * columns
2358	            && resolved_index < *footer_end * columns
2359	        {
2360	            // Skip footer, for the same reason.
2361	            resolved_index = *footer_end * columns;
2362	
2363	            if skip_rows {
2364	                // Ensure the cell's chosen column is kept after the
2365	                // footer.
2366	                resolved_index += initial_index % columns;
2367	            }
2368	        } else {
2369	            return Ok(resolved_index);
2370	        }
2371	    }
2372	}
2373	
2374	/// Computes the `y` of the next available empty row, given the auto index as
2375	/// an initial index for search, since we know that there are no empty rows
2376	/// before automatically-positioned cells, as they are placed sequentially.
2377	fn find_next_empty_row(
2378	    resolved_cells: &[Option<Entry>],
2379	    auto_index: usize,
2380	    columns: usize,
2381	) -> usize {
2382	    let mut resolved_index = auto_index.next_multiple_of(columns);
2383	    while resolved_cells
2384	        .get(resolved_index..resolved_index + columns)
2385	        .is_some_and(|row| row.iter().any(Option::is_some))
