2391	    resolved_index / columns
2392	}
2393	
2394	/// Fully merged rows under the cell of latest auto index indicate rowspans
2395	/// occupying all columns, so we skip the auto index until the shortest rowspan
2396	/// ends, such that, in the resulting row, we will be able to place an
2397	/// automatically positioned cell - and, in particular, hlines under it. The
2398	/// idea is that an auto hline will be placed after the shortest such rowspan.
2399	/// Otherwise, the hline would just be placed under the first row of those
2400	/// rowspans and disappear (except at the presence of column gutter).
2401	fn skip_auto_index_through_fully_merged_rows(
2402	    resolved_cells: &[Option<Entry>],
2403	    auto_index: &mut usize,
2404	    columns: usize,
2405	) {
2406	    // If the auto index isn't currently at the start of a row, that means
2407	    // there's still at least one auto position left in the row, ignoring
2408	    // cells with manual positions, so we wouldn't have a problem in placing
2409	    // further cells or, in this case, hlines here.
2410	    if *auto_index % columns == 0 {
2411	        while resolved_cells
2412	            .get(*auto_index..*auto_index + columns)
2413	            .is_some_and(|row| {
2414	                row.iter().all(|entry| matches!(entry, Some(Entry::Merged { .. })))
2415	            })
2416	        {
2417	            *auto_index += columns;
2418	        }
2419	    }
2420	}
